function renderProvenance(){const s=MISSIONS[S.mission];$('provenance').innerHTML=`<p><strong>${esc(s.name+' / '+s.instrument)}</strong><br>${esc(config().geology?.label||'Published geology')}</p>${S.mission==='zhurong'?`<p>${esc(config().geology?.notes||'')}</p>`:''}<p>Archive: ${esc((S.data.generated_at_utc||S.data.checked_date||'').slice(0,10))}<br>Spectroscopy review: ${esc(S.spectroscopy.research_date||S.spectroscopy.generated_at_utc||'source dated')}</p><p>Longitude east; Mars sphere radius 3,396,190 m. ${S.mission==='chemcam'?'ChemCam latitude convention is preserved as supplied and remains unspecified.':'Planetocentric latitude for the published map.'}</p><p>Point-to-unit joins are rover-position context. Distance and orientation tools use a spherical Mars approximation. Data retain original quality flags and source rows.</p>`;}
function renderSources(){const geo=config().geology||{},extra=S.catalog.sources?.[0];$('sources-content').innerHTML=`<h3>Published geology and structures</h3><p>${link('https://www.usgs.gov/maps/geologic-map-jezero-crater-and-nili-planum-region-mars','Sun & Stack (2020), USGS SIM 3464')} supplies Jezero’s 1:75,000 regional map. It is a pre-landing orbital interpretation. We retain published contacts, channels, ridge crests, crater rims, buried craters, delta fronts and lineaments as distinct classes.</p><p>The display line layer has ${number(extra?.display_feature_count,0)} features. The artificial map boundary is hidden; one source contact lacks geometry. Contact display simplification is 2 m, not an accuracy claim. The published web service is a viewing product; use the ${link('https://pubs.usgs.gov/sim/3464/','official GIS and map sheets')} for publication-grade spatial work.</p><p>Gale: ${link('https://doi.org/10.1029/2022JE007408','Fedo et al. (2022)')} and its ${link('https://doi.org/10.5281/zenodo.7041712','Glen Torridon map data')} provide local raster stratigraphy. Zhurong: ${link(S.geo.missions.zhurong?.geology?.source_url,S.geo.missions.zhurong?.geology?.attribution||'published southern Utopia map')} provides regional geomorphic units. ${esc(S.geo.missions.zhurong?.geology?.notes||'')}</p><h3>Imagery and geography</h3><ul>${(config().basemaps||[]).map(r=>`<li>${link(r.source_url,r.label)} — ${esc(r.attribution)}. ${esc(r.notes||'')}</li>`).join('')}</ul><h3>LIBS and spectroscopy</h3><p>${link('https://pds-geosciences.wustl.edu/missions/msl/chemcam.htm','NASA PDS ChemCam')} and ${link('https://pds-geosciences.wustl.edu/missions/mars2020/supercam.htm','NASA PDS SuperCam')} provide the archived oxide estimates. We display the validated shared archive, with calibration records excluded from geological analysis. Major oxides are not renormalized.</p><p>Raman acquisition locations and curated published findings are separate evidence types. Curiosity organic evidence comes from SAM; Curiosity has no Raman instrument. SHERLOC fluorescence is not uniquely organic and does not imply life.</p><ul>${(S.spectroscopy.sources||[]).filter(s=>s.doi).map(s=>`<li>${link(s.url,s.title)}</li>`).join('')}</ul><h3>Coordinate and inference limits</h3><p>Mars east longitude and latitude are not Earth WGS 84. Distances use a 3,396,190 m sphere; nearest-contact distance uses a local tangent approximation. Chemistry markers use rover positions, not surveyed laser footprints. Position uncertainty is not supplied for all points. Apparent precision at a unit boundary does not resolve a rock’s lithology.</p><p>Map overlap, cation ratios and descriptive statistics support exploration. They do not supply unique mineral identification, organic abundance, tectonic fault classification, or a continuous composition field across unsampled ground.</p><h3>Reproducible source records</h3><p><a href="./data/sources.json" download>New layer metadata and hashes</a> · <a href="../data/geography.json" download>Existing geography metadata</a> · <a href="https://github.com/manu-coder-space/mars-libs-explorer/tree/main/dist/Mar-to-gis" target="_blank" rel="noopener">Mar-to-gis source</a></p>`;}
function exportCSV(){if(!S.filtered.length){toast('No LIBS records in this selection. Zhurong’s original tables are linked in Observations.');return;}const ox=S.data.oxides||[],fields=['observation_id','target','mission','instrument','sol','raster_point','longitude_east_deg','latitude_deg','position_kind','latitude_convention','published_unit_under_rover','map_source','selected_metric','selected_metric_nonnegative_value','selected_metric_units','selected_metric_eligible',...ox.flatMap(o=>[o+'_wt_pct',o+'_RMSEP',o+'_shot_SD']),'quality_flags','source_id','source_row','source_url'];const cell=v=>{let s=String(v??'');if(/^[=+@\t\r]/.test(s)||/^-\D/.test(s))s="'"+s;return'"'+s.replace(/"/g,'""')+'"';};const rows=S.filtered.map(p=>[p.id,p.target,p.mission,p.instrument,p.sol,p.point,p.location?.lon,p.location?.lat,p.location?.kind,p.location?.latitude_convention,unitCode(p),unitCode(p)?geologySource():'',S.metric,M.computeMetric(p,S.metric),OXIDES[S.metric]?'wt_pct':S.metric==='mgNumber'?'molar_percent_total_Fe_as_FeO':'mol_per_mol',M.finite(M.computeMetric(p,S.metric)),...ox.flatMap(o=>[p.oxides?.[o],p.uncertainty?.rmsep?.[o],p.uncertainty?.shot_sd?.[o]]),quality(p).join('; '),p.source_id||p.provenance?.source_table_id,p.source_row??p.provenance?.source_row,scientificSource(p)]);download(`Mar-to-gis-${S.mission}-selection.csv`,'\ufeff'+[fields,...rows].map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('Exported original values, separate uncertainties, spatial context and source provenance.');}
function exportVectors(){const bounds=S.selection||map.getView(),features=[];for(const p of S.filtered){if(!p.location||!M.finite(p.location.lon)||!M.finite(p.location.lat))continue;features.push({type:'Feature',geometry:{type:'Point',coordinates:[p.location.lon,p.location.lat]},properties:{layer:'LIBS rover-position proxy',id:p.id,target:p.target,mission:p.mission,sol:p.sol,oxides_wt_pct:p.oxides,uncertainty:p.uncertainty,quality_flags:p.quality_flags,location_provenance:p.location,published_unit_under_rover:unitCode(p),map_source:geologySource(),source_url:scientificSource(p),source_row:p.source_row??p.provenance?.source_row}});}for(const e of visibleEvidence())features.push({type:'Feature',geometry:{type:'Point',coordinates:[e.lon,e.lat]},properties:{...e,layer:'spectroscopy evidence'}});if($('show-geology').checked)features.push(...S.basePolygons.features.filter(f=>intersects(M.featureBounds(f),bounds)).map(f=>({...f,properties:{...f.properties,layer:'published geological unit',source_url:geologySource()}})));features.push(...sourceLines().filter(f=>f.properties.kind==='contact'?$('show-contacts').checked:$('show-structures').checked&&(!$('structure-kind').value||f.properties.kind===$('structure-kind').value)).filter(f=>intersects(M.featureBounds(f),bounds)));features.push(...S.custom.filter(l=>l.mission===S.mission&&l.visible).flatMap(l=>l.data.features));download(`Mar-to-gis-${S.mission}-vectors.geojson`,JSON.stringify({type:'FeatureCollection',name:'Mar-to-gis',coordinate_system:CRS,crs_wkt:WKT,warning:'Planetary GeoJSON-style geometry; assign Mars CRS explicitly. Not RFC 7946 Earth WGS84.',exported_at_utc:new Date().toISOString(),mission:S.mission,selection:S.selection,map_view:map.getView(),notes:'Vector features intersecting the map view or selected area are retained whole, not clipped. LIBS records follow filters; rover proxies are not target footprints.',features}));toast('Exported Mars vectors with explicit planetary CRS and provenance. The .prj download is in Notes & provenance.');}
async function exportMap(){
 try{
  const image=new Image();image.src=map.exportPNG();await image.decode();
  const canvas=document.createElement('canvas'),scale=Math.min(devicePixelRatio||1,2),width=image.width/scale,mapHeight=image.height/scale;
  const measure=document.createElement('canvas').getContext('2d');measure.font='12px system-ui';
  const lines=[`${metricName()}: ${number(S.low)} to ${number(S.high)}. Marker colour = median at rover position.`,`${config().geology?.label||''}. Publication scale and coordinate uncertainties apply.`,
   S.mission==='zhurong'?'Landing position is context only. No verified LIBS target coordinates are plotted.':'Rover positions are proxies, not target footprints. No interpolation over unsampled terrain.',
   ...new Set((config().basemaps||[]).filter(r=>r.id===$('basemap').value||r.role==='regional').map(r=>r.attribution)),`Source: ${geologySource()}`,`Exported ${new Date().toISOString().slice(0,10)} · Sphere radius 3,396,190 m`];
  const wrapped=[];for(const line of lines){let row='';for(const word of String(line||'').split(' ')){if(row&&measure.measureText(row+word).width>width-36){wrapped.push(row.trimEnd());row='';}row+=word+' ';}wrapped.push(row.trimEnd());}
  canvas.width=image.width;canvas.height=image.height+Math.ceil((60+wrapped.length*18)*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#f7fafb';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0);ctx.scale(scale,scale);ctx.fillStyle='#20343d';ctx.font='600 17px system-ui';ctx.fillText(`Mar-to-gis · ${MISSIONS[S.mission].region}`,18,mapHeight+28);ctx.font='12px system-ui';wrapped.forEach((line,i)=>ctx.fillText(line,18,mapHeight+50+i*18));
  canvas.toBlob(blob=>{if(!blob){toast('Map export failed to produce an image.');return;}download(`Mar-to-gis-${S.mission}-map.png`,blob,'image/png');toast('Map image exported with source credits and spatial caveats.');});
 }catch(error){toast('Map export failed: '+error.message);}
}

const controlIds=['basemap','metric','sol-min','sol-max','search','unit-filter','exclude-flagged','show-geology','geology-opacity','show-contacts','show-structures','structure-kind','show-points','show-traverse','show-evidence','show-acquisitions','scatter-x','scatter-y'];
function savedWorkspace(){return{format:'Mar-to-gis-workspace',version:1,saved_at_utc:new Date().toISOString(),mission:S.mission,view:map.getView(),selection:S.selection,active_tab:S.activeTab,snapshot:S.data?.packaging?.source_data_sha256||null,controls:Object.fromEntries(controlIds.map(id=>[id,$(id).type==='checkbox'?$(id).checked:$(id).value])),notes:$('workspace-notes').value,custom_layers:S.custom,coordinate_system:CRS};}
function queueLocalSave(){if(!S.ready||restoringWorkspace)return;clearTimeout(persistTimer);persistTimer=setTimeout(persistLocal,750);}
function persistLocal(){if(!S.ready||restoringWorkspace||S.localSaveBlocked||!readSolRange())return false;try{localStorage.setItem(WORKSPACE_KEY,JSON.stringify(savedWorkspace()));return true;}catch{toast('This browser could not save the workspace locally. Use Save workspace to keep a JSON copy.');return false;}}
function applySavedControls(data){
 const changes=[];for(const[id,value]of Object.entries(data.controls||{})){
  if(!controlIds.includes(id))continue;const el=$(id);
  if(el.type==='checkbox'){if(typeof value!=='boolean')throw new Error(`Saved ${id} must be true or false.`);changes.push([el,value]);continue;}
  if(typeof value!=='string'&&typeof value!=='number')throw new Error(`Invalid saved ${id}.`);
  const text=String(value);if(el.tagName==='SELECT'&&![...el.options].some(o=>o.value===text))throw new Error(`Saved ${id} is unavailable for ${MISSIONS[S.mission].name}.`);
  if(id==='geology-opacity'&&(!M.finite(Number(value))||Number(value)<0||Number(value)>100))throw new Error('Saved geology opacity must be between 0 and 100.');
  if(['sol-min','sol-max'].includes(id)&&text!==''&&(!Number.isSafeInteger(Number(value))||Number(value)<0||Number(value)>S.maxSol))throw new Error(`Saved sol range must use whole numbers from 0 to ${S.maxSol}.`);
  if(id==='search'&&text.length>500)throw new Error('Saved target search exceeds 500 characters.');
  changes.push([el,text]);
 }
 const min=data.controls?.['sol-min'],max=data.controls?.['sol-max'];if(min!==undefined&&max!==undefined&&min!==''&&max!==''&&Number(min)>Number(max))throw new Error('Saved first sol must not be greater than last sol.');
 for(const[el,value]of changes){if(el.type==='checkbox')el.checked=value;else el.value=value;}
 if(data.selection){S.selection=[...data.selection];map.selection=[...data.selection];}
 $('workspace-notes').value=data.notes;renderCustomLayers();
}
function validBounds(b){return Array.isArray(b)&&b.length===4&&b.every(M.finite)&&b[0]<b[2]&&b[1]<b[3]&&b[0]>=-360&&b[2]<=720&&b[1]>=-90&&b[3]<=90;}
function validateLayer(data){
 if(data?.type!=='FeatureCollection'||!Array.isArray(data.features)||!data.features.length)throw new Error('Use a nonempty FeatureCollection with Mars longitude/latitude coordinates.');
 if(data.features.length>20000)throw new Error('Limit imported layers to 20,000 features.');
 if(data.coordinate_system?.body&&data.coordinate_system.body!=='Mars')throw new Error('The layer metadata identifies a body other than Mars.');
 let coordinates=0;
 const position=c=>{if(!Array.isArray(c)||c.length<2||c.length>3||!c.every(M.finite)||c[0]<-180||c[0]>360||Math.abs(c[1])>90)throw new Error('Each position must contain finite Mars longitude/latitude degrees, with optional elevation.');if(++coordinates>300000)throw new Error('Limit imported layers to 300,000 coordinate vertices.');};
 const line=c=>{if(!Array.isArray(c)||c.length<2)throw new Error('Each line must contain at least two positions.');c.forEach(position);if(!c.some(p=>p[0]!==c[0][0]||p[1]!==c[0][1]))throw new Error('A line must contain at least two distinct positions.');};
 const ring=c=>{if(!Array.isArray(c)||c.length<4)throw new Error('Each polygon ring needs at least four positions, including its closing position.');c.forEach(position);if(c[0][0]!==c.at(-1)[0]||c[0][1]!==c.at(-1)[1])throw new Error('Polygon rings must be closed.');if(new Set(c.map(p=>p[0]+','+p[1])).size<3)throw new Error('A polygon ring needs three distinct positions.');};
 const polygon=c=>{if(!Array.isArray(c)||!c.length)throw new Error('A polygon must have an outer ring.');c.forEach(ring);};
 const nonemptyParts=(c,fn)=>{if(!Array.isArray(c)||!c.length)throw new Error('Multipart geometry must contain at least one part.');c.forEach(fn);};
 for(const f of data.features){
  if(f?.type!=='Feature'||!['Point','LineString','MultiLineString','Polygon','MultiPolygon'].includes(f.geometry?.type))throw new Error('Supported geometry: Point, LineString, MultiLineString, Polygon, MultiPolygon.');
  const c=f.geometry.coordinates;switch(f.geometry.type){case'Point':position(c);break;case'LineString':line(c);break;case'MultiLineString':nonemptyParts(c,line);break;case'Polygon':polygon(c);break;case'MultiPolygon':nonemptyParts(c,polygon);break;}
  if(f.properties!==null&&f.properties!==undefined&&(typeof f.properties!=='object'||Array.isArray(f.properties)))throw new Error('Feature properties must be an object or null.');
  f.properties={...(f.properties||{}),kind:'user',color:'#db8e60',imported:true,label:String(f.properties?.label||f.properties?.name||'User interpretation').slice(0,200)};
 }
 return data;
}
function validateWorkspace(data){
 if(!data||data.format!=='Mar-to-gis-workspace'||data.version!==1||(typeof data.mission!=='string'||!Object.hasOwn(MISSIONS,data.mission)))throw new Error('This is not a supported Mar-to-gis workspace.');
 if(data.view!==null&&data.view!==undefined&&!validBounds(data.view))throw new Error('Invalid saved map bounds.');
 if(data.selection!==null&&data.selection!==undefined&&!validBounds(data.selection))throw new Error('Invalid saved selection bounds.');
 if(data.controls!==undefined&&(!data.controls||typeof data.controls!=='object'||Array.isArray(data.controls)))throw new Error('Saved controls must be an object.');
 if(data.notes!==undefined&&typeof data.notes!=='string')throw new Error('Saved notes must be text.');
 if((data.notes||'').length>50000)throw new Error('Limit saved notes to 50,000 characters.');
 const layers=data.custom_layers??[];if(!Array.isArray(layers)||layers.length>20)throw new Error('A workspace supports up to 20 imported layers.');
 const custom=layers.map((layer,i)=>{if(!layer||typeof layer.mission!=='string'||!Object.hasOwn(MISSIONS,layer.mission))throw new Error('Every imported layer must identify a supported Mars rover region.');if(typeof layer.visible!=='boolean')throw new Error('Imported layer visibility must be true or false.');if(typeof layer.name!=='string'||!layer.name.trim()||layer.name.length>200)throw new Error('Imported layers require a name of 1–200 characters.');return{id:'restored-'+i,name:layer.name,mission:layer.mission,visible:layer.visible,data:validateLayer(layer.data)};});
 const active=data.active_tab||'records';if(!['records','compare','chemistry','structure','notes'].includes(active))throw new Error('Invalid saved analysis tab.');
 return{format:data.format,version:1,mission:data.mission,view:data.view||null,selection:data.selection||null,snapshot:typeof data.snapshot==='string'?data.snapshot:null,controls:data.controls||{},notes:data.notes||'',custom_layers:custom,active_tab:active};
}
async function importLayer(file){if(!file)return;if(!$('confirm-mars').checked){toast('Confirm that your layer uses Mars longitude/latitude degrees before importing.');return;}try{if(file.size>8*1024*1024)throw new Error('Use a vector layer smaller than 8 MB.');const data=validateLayer(JSON.parse(await file.text()));if(S.custom.length>=20)throw new Error('Remove a layer before adding more than 20 imported layers.');S.custom.push({id:'user-'+Date.now(),name:file.name.slice(0,200),mission:S.mission,visible:true,data});renderCustomLayers();setMapData();persistLocal();toast('Imported '+data.features.length+' features as your interpretation layer.');}catch(error){toast(error.message);}}
function renderCustomLayers(){$('custom-layers').innerHTML=S.custom.filter(l=>l.mission===S.mission).map(l=>`<div><label><input type="checkbox" data-custom-toggle="${esc(l.id)}" ${l.visible?'checked':''}> ${esc(l.name)}</label><button data-custom-remove="${esc(l.id)}">Remove</button></div>`).join('');}
function restoredMessage(data){return data.snapshot&&data.snapshot!==S.data?.packaging?.source_data_sha256?'Restored workspace using the current validated archive. Its data snapshot differs from the saved one.':'Restored your saved Mar-to-gis map, filters, notes and imported layers.';}
async function restoreWorkspace(file){
 if(!file)return;try{
  if(file.size>MAX_WORKSPACE_BYTES)throw new Error('Workspace file exceeds 16 MB.');
  const data=validateWorkspace(JSON.parse(await file.text())),previous=S.ready?savedWorkspace():null,previousLayers=S.custom;restoringWorkspace=true;S.custom=data.custom_layers;
  const ok=await switchMission(data.mission,data);
  if(!ok){const reason=$('error').textContent;S.custom=previousLayers;if(previous)await switchMission(previous.mission,validateWorkspace(previous));restoringWorkspace=false;throw new Error('Workspace was not restored: '+reason);}
  restoringWorkspace=false;S.localSaveBlocked=false;persistLocal();toast(restoredMessage(data));
 }catch(error){restoringWorkspace=false;toast(error.message);}
}
async function updateStatus(){try{const status=await json('../data/update-status.json');S.update=status;const date=v=>v?new Date(v).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}):'not available';$('update-status').textContent=`${status.schedule?.is_enabled?'Archive checks daily at '+status.schedule.local_time+' '+status.schedule.timezone+'. ':''}Last check: ${date(status.last_checked_at_utc)}. Last accepted data: ${date(status.last_data_update_at_utc)}.${status.last_result==='held'?' New data are held for review.':''}${status.source_errors?.length?' Some source checks need attention.':''}`;}catch{$('update-status').textContent='Update status unavailable. The loaded archive retains its source dates.';}}
function bind(){
 document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>switchMission(b.dataset.mission));document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-mode]').forEach(v=>{v.classList.toggle('active',v===b);v.setAttribute('aria-pressed',String(v===b));});map.setMode(b.dataset.mode);$('tool-help').textContent=b.dataset.mode==='select'?'Drag a rectangle to select measurements; Clear restores all filtered records.':b.dataset.mode==='measure'?'Click vertices to measure a surface path. Double-click or press Enter to finish.':'Select a marker or geological unit. Drag to pan; scroll or pinch to zoom.';});
 for(const id of['search','sol-min','sol-max'])$(id).addEventListener('input',()=>{clearTimeout(filterTimer);filterTimer=setTimeout(applyFilters,180);});for(const id of['metric','unit-filter','exclude-flagged'])$(id).addEventListener('change',applyFilters);
 for(const id of['basemap','show-geology','geology-opacity'])$(id).addEventListener('input',()=>{setMapData();drawActiveCharts();queueLocalSave();});for(const id of['show-contacts','show-structures','structure-kind','show-points','show-traverse','show-evidence','show-acquisitions'])$(id).addEventListener('change',()=>{updateMapStyle();updateSummary();renderRecords();drawActiveCharts();queueLocalSave();});
 $('fit-rover').onclick=fitRover;$('fit-geology').onclick=fitGeology;$('zoom-in').onclick=()=>map.zoom(.7);$('zoom-out').onclick=()=>map.zoom(1/.7);$('clear-selection').onclick=()=>{S.selection=null;map.clearSelection();map.clearMeasure();applyFilters();};$('reset-filters').onclick=()=>{$('search').value='';$('sol-min').value=S.minSol;$('sol-max').value=S.maxSol;$('unit-filter').value='';$('exclude-flagged').checked=false;S.selection=null;map.clearSelection();applyFilters();};
 document.body.addEventListener('click',e=>{const p=e.target.closest('[data-point]');if(p)inspectPoint(p.dataset.point);const evidence=e.target.closest('[data-evidence]');if(evidence){const item=S.evidence.find(v=>v.id===evidence.dataset.evidence);if(item)inspectEvidence(item);}const u=e.target.closest('[data-unit]');if(u){const unit=(config().geology?.units||[]).find(v=>v.code===u.dataset.unit);if(unit){$('inspector-type').textContent='MAP LEGEND';$('inspector-content').innerHTML=unitDetails({properties:unit});}}const remove=e.target.closest('[data-custom-remove]');if(remove){S.custom=S.custom.filter(l=>l.id!==remove.dataset.customRemove);renderCustomLayers();setMapData();persistLocal();}});
 $('custom-layers').addEventListener('change',e=>{const id=e.target.dataset.customToggle,l=S.custom.find(v=>v.id===id);if(l){l.visible=e.target.checked;setMapData();persistLocal();}});
 $('page-prev').onclick=()=>{S.page--;renderRecords();};$('page-next').onclick=()=>{S.page++;renderRecords();};document.querySelectorAll('[data-tab]').forEach((b,i,buttons)=>{b.onclick=()=>setTab(b.dataset.tab);b.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const next=buttons[(i+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length];next.focus();setTab(next.dataset.tab);}};});$('scatter-x').onchange=()=>{drawScatter();queueLocalSave();};$('scatter-y').onchange=()=>{drawScatter();queueLocalSave();};
 $('export-csv').onclick=exportCSV;$('export-geojson').onclick=exportVectors;$('export-map').onclick=exportMap;$('export-crs').onclick=()=>download('Mars_2000_Sphere.prj',WKT,'text/plain');$('save-session').onclick=()=>{if(!S.ready||!readSolRange()){toast('Wait for the archive and correct the sol range before saving.');return;}S.localSaveBlocked=false;persistLocal();download('Mar-to-gis-workspace.json',JSON.stringify(savedWorkspace(),null,2));toast('Saved Mar-to-gis workspace: region, view, filters, selection, notes and custom layers.');};$('import-layer').onchange=e=>{importLayer(e.target.files[0]);e.target.value='';};$('restore-session').onchange=e=>{restoreWorkspace(e.target.files[0]);e.target.value='';};$('workspace-notes').oninput=queueLocalSave;window.addEventListener('pagehide',()=>{clearTimeout(persistTimer);persistLocal();});
 $('sources-open').onclick=()=>$('sources-dialog').showModal();$('sources-close').onclick=()=>$('sources-dialog').close();$('sources-dialog').onclick=e=>{if(e.target===$('sources-dialog'))$('sources-dialog').close();};
 new ResizeObserver(()=>drawActiveCharts()).observe($('analysis-panel')||document.querySelector('.analysis-panel'));
}
async function init(){
 map=new window.MarsGISMap($('map'),{onPick:renderInspector,onSelection:bounds=>{S.selection=bounds;applyFilters();toast('Area selected. Tables and chemistry now follow this rectangle.');},onMeasure:(distance,vertices)=>{S.measure={distance_m:distance,vertices};$('measure-readout').textContent=vertices.length?`≈ ${distance>=1000?number(distance/1000,2)+' km':number(distance,0)+' m'} · Mars sphere`:'';},onView:()=>{if(S.activeTab==='structure')drawRose();queueLocalSave();},onStatus:message=>toast(message)});bind();if(innerWidth<=800)$('layers-details').open=false;
 try{
  [S.geo,S.spectroscopy,S.catalog]=await Promise.all([json('../data/geography.json'),json('../data/spectroscopy.json'),json('./data/sources.json')]);
  S.lines=await json('./data/jezero-lines.geojson',S.catalog.layers.find(l=>l.id==='jezero-lines').sha256);
  let prior=null,restoreProblem='';
  try{const text=localStorage.getItem(WORKSPACE_KEY);if(text){if(text.length>MAX_WORKSPACE_BYTES)throw new Error('The saved workspace exceeds 16 MB.');prior=validateWorkspace(JSON.parse(text));}}
  catch(error){restoreProblem='The browser workspace was not restored: '+error.message;}
  let ok=false;if(prior){restoringWorkspace=true;S.custom=prior.custom_layers;ok=await switchMission(prior.mission,prior);restoringWorkspace=false;if(ok)toast(restoredMessage(prior));else restoreProblem='Saved workspace settings could not be applied. Opened the default Jezero view.';}
  if(restoreProblem)S.localSaveBlocked=true;
  if(!ok){S.custom=[];await switchMission('supercam');}
  if(restoreProblem)toast(restoreProblem+' The previous local save is retained; Save workspace replaces it.');await updateStatus();
 }catch(error){restoringWorkspace=false;$('map-loading').hidden=true;fail(error);}

}
