window.MarToGIS={version:'1.0.0',getSummary:()=>({mission:S.mission,records:S.filtered.length,locations:S.groups.length,lines:sourceLines().length,selection:S.selection,snapshot:S.data?.packaging?.source_data_sha256||null})};
